declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$root=dirname(__DIR__);$target=(string)($argv[1]??'');if($target===''){$dirs=glob($root.'/storage/update-backups/experience-v2-*',GLOB_ONLYDIR)?:[];rsort($dirs);$target=$dirs[0]??'';}if(!$target||!is_dir($target.'/files')){fwrite(STDERR,"Backup V2 não encontrado.\n");exit(1);}$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($target.'/files',FilesystemIterator::SKIP_DOTS));$count=0;foreach($it as $f){if(!$f->isFile())continue;$rel=substr($f->getPathname(),strlen($target.'/files')+1);$dst=$root.'/'.$rel;if(!is_dir(dirname($dst)))mkdir(dirname($dst),0750,true);if(!copy($f->getPathname(),$dst)){fwrite(STDERR,"Falha: {$rel}\n");exit(1);}$count++;}echo"Rollback de código: {$count} arquivos. Migrations aditivas preservadas para evitar perda de dados.\n";
